def dijkstra_array(n, edges, src=0):
    g = [[] for _ in range(n)]
    for u, v, w in edges:
        g[u].append((v, w))
    dist = [float('inf')] * n
    dist[src] = 0
    settled = [False] * n
    for _ in range(n):
        u = -1
        best = float('inf')
        for i in range(n):
            if not settled[i] and dist[i] < best:
                best, u = dist[i], i
        if u < 0:
            break
        settled[u] = True
        for v, w in g[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    return dist

import heapq
from collections import defaultdict

def dijkstra(n, edges, src=0):
    g = defaultdict(list)
    for u, v, w in edges:
        g[u].append((v, w))
    dist = [float('inf')] * n
    dist[src] = 0
    h = [(0, src)]
    while h:
        d, u = heapq.heappop(h)  # closest first
        if d != dist[u]:
            continue  # stale
        for v, w in g[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(h, (nd, v))
    return dist

